/// Which picture to show. A frame lasts 100ms, the same as buzz's `sleep 0.1`.
pub fn frame_index() -> usize {
    static START: std::sync::OnceLock<Instant> = std::sync::OnceLock::new();
    let start = START.get_or_init(Instant::now);
    (start.elapsed().as_millis() as usize / 100) % FRAMES.len()
}

/// One frame as centred lines of half-blocks. `▄` keeps its foreground on the
/// lower half and its background on the upper, as buzz drew it.
pub fn picture(index: usize) -> Vec<Line<'static>> {
    parse(FRAMES[index % FRAMES.len()])
}

fn parse(frame: &str) -> Vec<Line<'static>> {
    frame
        .split('\n')
        .filter(|row| !row.is_empty())
        .map(parse_row)
        .collect()
}

fn parse_row(row: &str) -> Line<'static> {
    let mut spans: Vec<Span<'static>> = Vec::new();
    let mut style = Style::default();
    let mut chars = row.chars();
    let mut width = 0usize;
    while let Some(c) = chars.next() {
        if c != '\u{1b}' {
            push(&mut spans, c, style);
            width += 1;
            continue;
        }
        let mut params = String::new();
        if chars.next() != Some('[') {
            continue;
        }
        let cmd = loop {
            match chars.next() {
                Some(d) if d.is_ascii_digit() || d == ';' => params.push(d),
                Some(d) => break d,
                None => break ' ',
            }
        };
        let nums: Vec<u16> = if params.is_empty() {
            Vec::new()
        } else {
            params.split(';').filter_map(|n| n.parse().ok()).collect()
        };
        match cmd {
            'C' => {
                let n = nums.first().copied().unwrap_or(1) as usize;
                for _ in 0..n {
                    push(&mut spans, ' ', Style::default());
                    width += 1;
                }
            }
            'm' => style = sgr(style, &nums),
            _ => {}
        }
    }
    while width < WIDTH {
        push(&mut spans, ' ', Style::default());
        width += 1;
    }
    Line::from(spans)
}

fn push(spans: &mut Vec<Span<'static>>, c: char, style: Style) {
    if let Some(last) = spans.last_mut()
        && last.style == style
    {
        last.content.to_mut().push(c);
    } else {
        spans.push(Span::styled(c.to_string(), style));
    }
}

fn sgr(style: Style, nums: &[u16]) -> Style {
    if nums.is_empty() || nums == [0] {
        return Style::default();
    }
    let mut style = style;
    let mut i = 0;
    while i < nums.len() {
        match nums[i] {
            0 => {
                style = Style::default();
                i += 1;
            }
            38 if nums.get(i + 1) == Some(&2) && i + 4 < nums.len() => {
                style = style.fg(Color::Rgb(nums[i + 2] as u8, nums[i + 3] as u8, nums[i + 4] as u8));
                i += 5;
            }
            48 if nums.get(i + 1) == Some(&2) && i + 4 < nums.len() => {
                style = style.bg(Color::Rgb(nums[i + 2] as u8, nums[i + 3] as u8, nums[i + 4] as u8));
                i += 5;
            }
            _ => i += 1,
        }
    }
    style
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn five_frames_of_ten_coloured_rows() {
        assert_eq!(FRAMES.len(), 5);
        for (i, frame) in FRAMES.iter().enumerate() {
            let lines = parse(frame);
            assert_eq!(lines.len(), HEIGHT, "frame {i}");
            let coloured = lines.iter().flat_map(|l| l.spans.iter()).any(|s| {
                matches!(s.style.fg, Some(Color::Rgb(_, _, _))) && s.content.chars().any(|c| c == '\u{2584}' || c == '\u{2580}')
            });
            assert!(coloured, "frame {i} has a truecolor half-block");
            let wide = lines.iter().all(|l| l.spans.iter().map(|s| s.content.chars().count()).sum::<usize>() == WIDTH);
            assert!(wide, "frame {i} is padded to {WIDTH}");
        }
    }
}
